#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *cov_array;

    // Parse NumPy arrays
    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &cov_array))
        return NULL;

    // Get dimensions
    int n = (int)PyArray_DIM(weights_array, 0);

    // Get data pointers with C-contiguous layout
    double *weights = (double*)PyArray_DATA(weights_array);
    double *cov = (double*)PyArray_DATA(cov_array);

    // Step 1: Calculate temp = S * x (matrix-vector multiply)
    double *temp = (double*)malloc(n * sizeof(double));
    if (temp == NULL) {
        PyErr_SetString(PyExc_MemoryError, "Failed to allocate memory for temp vector");
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        double row_sum = 0.0;
        for (int j = 0; j < n; j++) {
            row_sum += cov[i * n + j] * weights[j];
        }
        temp[i] = row_sum;
    }

    // Step 2: Calculate x^T * temp (dot product)
    double risk_squared = 0.0;
    for (int i = 0; i < n; i++) {
        risk_squared += weights[i] * temp[i];
    }

    free(temp);

    // Handle small negative values due to floating point errors
    if (risk_squared < 0.0) {
        risk_squared = 0.0;
    }

    double risk = sqrt(risk_squared);

    return PyFloat_FromDouble(risk);
}

